CREATE TABLE members (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE modules (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), code TEXT NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(project_id,code));
CREATE TABLE supports (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL DEFAULT 'cái', image_url TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE plans (id TEXT PRIMARY KEY, module_id TEXT NOT NULL REFERENCES modules(id), support_id TEXT NOT NULL REFERENCES supports(id), required REAL NOT NULL CHECK(required > 0), completed REAL NOT NULL DEFAULT 0 CHECK(completed >= 0), started INTEGER NOT NULL DEFAULT 0, UNIQUE(module_id,support_id));
CREATE TABLE batches (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES plans(id), qty REAL NOT NULL CHECK(qty > 0), work_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', photo_url TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, voided INTEGER NOT NULL DEFAULT 0, void_reason TEXT NOT NULL DEFAULT '');
CREATE TRIGGER batch_add BEFORE INSERT ON batches BEGIN SELECT CASE WHEN (SELECT completed + NEW.qty > required FROM plans WHERE id=NEW.plan_id) THEN RAISE(ABORT,'Vượt số lượng yêu cầu') END; END;
CREATE TRIGGER batch_added AFTER INSERT ON batches BEGIN UPDATE plans SET completed=completed+NEW.qty, started=1 WHERE id=NEW.plan_id; END;
CREATE TRIGGER batch_void AFTER UPDATE OF voided ON batches WHEN OLD.voided=0 AND NEW.voided=1 BEGIN UPDATE plans SET completed=completed-OLD.qty WHERE id=OLD.plan_id; END;
CREATE TABLE drawings (id TEXT PRIMARY KEY, support_id TEXT REFERENCES supports(id), kind TEXT NOT NULL CHECK(kind IN ('typical','detail')), code TEXT NOT NULL, revision TEXT NOT NULL DEFAULT '', issue_date TEXT NOT NULL DEFAULT '', file_url TEXT NOT NULL, file_type TEXT NOT NULL CHECK(file_type IN ('pdf','dwg','image')), current INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE materials (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, specification TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL, stock REAL NOT NULL DEFAULT 0 CHECK(stock >= 0), note TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE stock_moves (id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES materials(id), kind TEXT NOT NULL CHECK(kind IN ('IN','OUT','RETURN','ADJUST')), qty REAL NOT NULL CHECK(qty != 0), move_date TEXT NOT NULL, project_id TEXT REFERENCES projects(id), module_id TEXT REFERENCES modules(id), plan_id TEXT REFERENCES plans(id), source TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER move_add BEFORE INSERT ON stock_moves BEGIN SELECT CASE WHEN (SELECT stock + NEW.qty < 0 FROM materials WHERE id=NEW.material_id) THEN RAISE(ABORT,'Không đủ tồn kho') END; END;
CREATE TRIGGER move_added AFTER INSERT ON stock_moves BEGIN UPDATE materials SET stock=stock+NEW.qty WHERE id=NEW.material_id; END;
CREATE TABLE audit (id TEXT PRIMARY KEY, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, actor TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_plans_module ON plans(module_id);
CREATE INDEX idx_batches_plan ON batches(plan_id);
CREATE INDEX idx_stock_material ON stock_moves(material_id);
